      questions: [
        { q: 'Que signifie l\'acronyme TAEG dans un crédit immobilier ?',
          options: ['Taux Annuel d\'Endettement Garanti', 'Taux Annuel Effectif Global', 'Taxe d\'Acquisition de l\'État sur les Garanties', 'Taux Ajustable d\'Emprunt Général'],
          correct: 1, rationale: 'Autrefois appelé TEG, c\'est la boussole incontournable pour comparer le coût de plusieurs prêts.' },
        { q: 'À quoi sert concrètement le TAEG pour l\'emprunteur ?',
          options: ['À déterminer la surface achetable', 'C\'est un outil de transparence qui permet de comparer le VRAI coût total de différentes offres de prêt, car il inclut tous les frais obligatoires (pas seulement les intérêts)', 'À payer le notaire', 'À calculer la plus-value immobilière'],
          correct: 1, rationale: 'Une banque peut vous appâter avec un taux d\'intérêt très bas, mais se rattraper avec une assurance et des frais de dossier très chers. Le TAEG révèle la vérité.' },
        { q: 'Comparé au taux nominal (le taux d\'intérêt de base du prêt), comment se situe le TAEG ?',
          options: ['Il est souvent inférieur', 'Il est toujours strictement égal', 'Il est systématiquement supérieur, puisqu\'il additionne le taux nominal et tous les autres frais liés au crédit', 'Il n\'a aucun lien avec le taux nominal'],
          correct: 2, rationale: 'Taux Nominal + Coût de l\'assurance + Frais de dossier + Garanties = TAEG.' },
        { q: 'Lequel de ces éléments N\'EST PAS inclus dans le calcul du TAEG d\'un crédit immobilier ?',
          options: ['Les frais de dossier bancaires', 'Le coût de l\'assurance emprunteur obligatoire (décès/invalidité)', 'Les "frais de notaire" (Droits de mutation et taxes liés à l\'achat du bien immobilier lui-même)', 'Les frais de garantie (hypothèque, caution Crédit Logement)'],
          correct: 2, rationale: 'Le TAEG évalue le coût du crédit, pas le coût de l\'achat. Les frais de mutation ne rémunèrent pas la banque ni le crédit, ce sont des impôts d\'État.' },
        { q: 'Qu\'est-ce que le "Taux d\'Usure" par rapport au TAEG ?',
          options: ['Le taux minimum auquel la banque accepte de prêter', 'C\'est le TAEG maximal (plafond légal fixé par la Banque de France) au-delà duquel il est formellement interdit à une banque d\'accorder un prêt', 'La pénalité pour remboursement anticipé', 'Le taux d\'usure de l\'appartement'],
          correct: 1, rationale: 'Le taux d\'usure protège l\'emprunteur contre des conditions financières abusives qui pourraient le ruiner.' },
        { q: 'Une banque vous propose un crédit. Le calcul montre que le TAEG dépasse le taux d\'usure actuel. Quelle est la conséquence immédiate ?',
          options: ['La banque augmente ses frais de dossier', 'Le prêt est automatiquement refusé (dossier bloqué), car prêter au-dessus de l\'usure est un délit', 'L\'emprunteur doit payer une amende', 'La durée du prêt est divisée par deux'],
          correct: 1, rationale: 'C\'est ce qui a causé de nombreux blocages de crédits en 2022 et 2023 : les taux bancaires remontaient vite, mais le plafond légal de l\'usure ne suivait pas assez vite.' },
        { q: 'Sur un document de prêt, l\'affichage du TAEG est-il facultatif ?',
          options: ['Oui, c\'est juste un indicateur commercial', 'Non, il est strictement obligatoire sur toute publicité, offre préalable et contrat de prêt, sous peine de nullité du taux', 'Uniquement pour les prêts de plus de 200 000 €', 'Oui, sauf si l\'emprunteur est courtier'],
          correct: 1, rationale: 'Si la banque fait une erreur mathématique substantielle ou omet le TAEG, le juge peut sanctionner la banque en remplaçant le taux du crédit par le taux d\'intérêt légal (très faible).' },
        { q: 'Comment un emprunteur peut-il faire baisser son TAEG de manière très efficace, sans renégocier le taux d\'intérêt de la banque ?',
          options: ['En supprimant les fenêtres de la maison', 'En ayant recours à la "délégation d\'assurance" (prendre une assurance emprunteur externe souvent 2 fois moins chère que celle de la banque)', 'En allongeant la durée du crédit à 30 ans', 'En cachant ses crédits à la consommation'],
          correct: 1, rationale: 'L\'assurance pesant très lourd dans le TAEG, trouver une assurance moins chère fera mécaniquement chuter le TAEG global (et permettra parfois de repasser sous le taux d\'usure).' },
        { q: '(Challenge) Un client passe par un courtier en crédit immobilier. Le courtier facture 1 500 € d\'honoraires pour le montage du dossier (frais obligatoires pour l\'obtention du prêt). Ces frais de courtage doivent-ils être intégrés dans le calcul du TAEG ?',
          options: ['Non, car ce n\'est pas la banque qui les facture', 'Oui, tous les frais obligatoires pour obtenir le prêt (même facturés par des tiers) doivent entrer dans le calcul du TAEG', 'Uniquement la moitié des frais', 'Non, le courtier est invisible pour la banque'],
          correct: 1, rationale: 'C\'est la règle d\'or du TAEG. Si vous êtes obligé de payer ce courtier pour avoir le prêt de cette banque, c\'est un coût du crédit, cela gonfle donc le TAEG.' },
        { q: '(Challenge) Sur quel capital se base le calcul des frais dans la formule mathématique du TAEG ?',
          options: ['Sur le prix affiché de la maison en vitrine d\'agence', 'Sur le revenu net annuel du foyer', 'Sur le capital effectivement emprunté (montant mis à disposition par la banque)', 'Sur le total du patrimoine de l\'acheteur'],
          correct: 2, rationale: 'Le TAEG reflète le coût de l\'argent prêté. Il se calcule donc sur la somme exacte que la banque va vous avancer (prix du bien + frais divers - apport personnel).' },
      ],
