      id: 'w9-d3', dayName: 'Jeudi', theme: 'Transmission',
      title: 'L\'indivision - bases',
      questions: [
        { q: 'En droit civil et immobilier, qu\'est-ce que l\'indivision ?',
          options: ['Un bien qui ne peut pas être coupé en deux', 'La situation juridique où plusieurs personnes sont propriétaires ensemble (co-propriétaires) d\'un même bien ou d\'un même patrimoine', 'Un contrat de location à plusieurs', 'L\'interdiction de vendre sa maison'],
          correct: 1, rationale: 'Chaque indivisaire possède une "quote-part" (ex: 50% ou 1/3) du bien, mais cette part est abstraite, elle ne correspond pas à une pièce physique de la maison.' },
        { q: 'Quelles sont les deux situations les plus courantes qui créent une indivision sans que les personnes ne l\'aient particulièrement souhaité (indivision subie) ?',
          options: ['L\'achat d\'une voiture et la location d\'un studio', 'Une succession (les enfants héritent ensemble de la maison des parents) et un divorce (le couple marié en communauté se sépare)', 'La création d\'une entreprise et l\'achat d\'un parking', 'Le voisinage et la copropriété'],
          correct: 1, rationale: 'Lors d\'un décès, avant le partage définitif, tous les héritiers sont propriétaires en indivision. C\'est souvent là que naissent les conflits.' },
        { q: 'Comment se nomment les personnes qui partagent la propriété dans cette situation ?',
          options: ['Les colocataires', 'Les usufruitiers', 'Les indivisaires', 'Les actionnaires'],
          correct: 2, rationale: 'Ils détiennent chacun des droits de même nature sur le bien.' },
        { q: 'Dans une indivision classique, quelle est la règle pour prendre la décision la plus grave : "VENDRE" le bien immobilier (acte de disposition) ?',
          options: ['Il suffit de la majorité absolue (51%)', 'L\'accord de l\'indivisaire le plus âgé suffit', 'Il faut obligatoirement l\'UNANIMITÉ (l\'accord de 100% des indivisaires)', 'C\'est le notaire qui décide seul'],
          correct: 2, rationale: 'C\'est le grand point de blocage de l\'indivision. Si trois frères possèdent un bien et qu\'un seul refuse de vendre, la vente amiable est bloquée.' },
        { q: 'Pour les actes "d\'administration" courante (faire des réparations, renouveler un bail d\'habitation), quelle règle de majorité s\'applique ?',
          options: ['L\'unanimité (100%)', 'La majorité des deux tiers (2/3) des droits indivis', 'Celui qui a la plus grosse part décide de tout', 'Le vote du maire'],
          correct: 1, rationale: 'La loi a assoupli la gestion courante. Attention, on parle des 2/3 des "droits" (les pourcentages de détention), pas forcément des 2/3 des "personnes".' },
        { q: 'Si une indivision se passe mal, que dit le célèbre article 815 du Code Civil ?',
          options: ['"La majorité a toujours raison"', '"Le bien appartient au premier occupant"', '"Nul ne peut être contraint à demeurer dans l\'indivision et le partage peut toujours être provoqué"', '"L\'indivision dure 99 ans"'],
          correct: 2, rationale: 'C\'est une règle d\'ordre public. Si vous voulez sortir de l\'indivision, personne ne peut vous obliger à y rester (vous pouvez forcer le partage ou la vente en justice).' },
        { q: 'Que peuvent faire des indivisaires qui s\'entendent bien pour organiser sereinement la gestion du bien (ex: maison de famille) sur le long terme ?',
          options: ['Créer une association loi 1901', 'Signer une "convention d\'indivision" devant notaire (pour une durée déterminée, max 5 ans renouvelable) fixant les règles de gestion et la répartition des frais', 'Vendre le bien au plus jeune', 'Rien, la loi interdit de s\'organiser'],
          correct: 1, rationale: 'Ce contrat permet de désigner un gérant, de prévoir qui utilise la maison en juillet ou en août, et comment se paient la taxe foncière et les travaux.' },
        { q: 'Si un des indivisaires veut vendre sa quote-part (ex: ses 25%) à un étranger à la famille, de quel droit bénéficient les autres indivisaires ?',
          options: ['Aucun droit, il vend à qui il veut', 'Du droit d\'expulsion de l\'étranger', 'Du droit de préemption : ils sont prioritaires pour racheter cette part aux mêmes prix et conditions', 'Du droit d\'augmenter le prix'],
          correct: 2, rationale: 'Le vendeur doit notifier ses co-indivisaires par acte d\'huissier. Cela permet de garder le bien "dans la famille" et d\'éviter qu\'un inconnu ne s\'immisce dans l\'indivision.' },
        { q: '(Challenge) Trois sœurs héritent d\'une maison (chacune a 33,3% des parts, soit 1/3). Deux veulent vendre (soit 66,6% des droits, donc les 2/3), la dernière s\'y oppose et bloque tout. Que peuvent faire les deux premières ?',
          options: ['Rien, l\'unanimité étant requise, le dossier est définitivement classé', 'Elles peuvent vendre leurs deux tiers à la mairie sans l\'accord de la dernière', 'Grâce à la loi de 2009, détenant au moins les 2/3 des droits indivis, elles peuvent aller devant le tribunal pour obtenir l\'autorisation judiciaire de forcer la vente aux enchères (licitation) du bien', 'Elles peuvent louer la maison de force'],
          correct: 2, rationale: 'Pour lutter contre les indivisions totalement bloquées par un héritier récalcitrant, la loi autorise la vente forcée si les demandeurs pèsent au moins les 2/3 de l\'indivision.' },
        { q: '(Challenge) Lors d\'un achat immobilier entre concubins, quelle est la grande alternative juridique à l\'achat en "indivision" (qui est précaire) ?',
          options: ['La tontine', 'L\'achat au nom d\'un seul', 'La création d\'une SCI (Société Civile Immobilière) : ce n\'est plus l\'indivision, c\'est la société (personne morale) qui est propriétaire de l\'immeuble, et les concubins détiennent des parts de la société', 'L\'hypothèque'],
          correct: 2, rationale: 'La SCI permet de contrer les règles rigides de l\'indivision. Les concubins rédigent des statuts sur-mesure (désignation d\'un gérant, règles de majorité adaptées) pour protéger le patrimoine.' },
      ],
