          options: ['Oui, l\'assurance paie toujours pour les mineurs, même pour une faute intentionnelle, car les parents sont civilement responsables des actes de leurs enfants', 'Non, la faute intentionnelle annule toujours la garantie, les parents devront payer de leur poche à vie', 'L\'État paie à la place des parents', 'Le principal du collège est jugé responsable'],
