          options: ['Seulement si la maison de vacances est en France', 'Oui, la loi l\'autorise. L\'avantage fiscal porte sur les dépenses effectuées pour la résidence principale ET pour les résidences secondaires du contribuable', 'Non, c\'est exclusif à la résidence principale', 'La réduction tombe à 10 %'],
