          options: ['Pour les ministres', 'Pour les femmes enceintes', 'Les victimes de MOINS de 16 ans, de PLUS de 70 ans, et les grands invalides (taux > 80%). Leurs dommages corporels sont systématiquement indemnisés (sauf s\'ils ont recherché volontairement le dommage)', 'Pour les fonctionnaires'],
