          options: ['Il faut que l\'action ait été acquise AVANT le 1er janvier 2018 (avant la réforme Macron/PFU). Les actions achetées après 2018 n\'y ont plus droit', 'Il faut être retraité', 'Il faut l\'autorisation de l\'entreprise', 'L\'action doit valoir plus de 100 000 €'],
