          options: ['Le prêt de la CAF', 'La garantie de l\'assurance maladie', 'Le Crédit Logement', 'La Garantie VISALE (gérée par Action Logement), qui se porte caution solidaire gratuitement à la place des parents et rembourse jusqu\'à 36 mois de loyers impayés'],
