      id: 'w26-d3', dayName: 'Jeudi', theme: 'Transmission',
      title: 'Testament authentique vs olographe',
      questions: [
        { q: 'Qu\'est-ce qu\'un testament "olographe" (le plus courant en France) ?',
          options: ['Un testament enregistré en vidéo (smartphone)', 'Un testament rédigé entièrement à la main, daté et signé par le testateur (celui qui rédige), sans l\'intervention obligatoire d\'un notaire lors de la rédaction', 'Un testament tapé à l\'ordinateur et imprimé', 'Un document verbal devant trois témoins'],
          correct: 1, rationale: 'C\'est la forme la plus simple, la plus secrète et la moins coûteuse (gratuite).' },
        { q: 'Quelle est la conséquence d\'un testament "olographe" qui serait tapé à l\'ordinateur, même s\'il est daté et signé au stylo ?',
          options: ['Il est parfaitement valable', 'Il perd sa valeur pour l\'immobilier', 'Il n\'est valable que s\'il fait moins d\'une page', 'Il est frappé de nullité absolue. L\'écriture manuscrite (de la main) de l\'intégralité du texte est une condition "ad validitatem" (vitale)'],
          correct: 3, rationale: 'L\'écriture manuscrite est le seul moyen pour le juge de vérifier que c\'est bien la personne elle-même qui a rédigé le document (expertise graphologique), sans contrainte.' },
        { q: 'Quel est l\'inconvénient majeur du testament olographe conservé chez soi (dans un tiroir ou un livre) ?',
          options: ['Il expire au bout de 5 ans', 'Il est lourdement taxé', 'Le risque de perte, de destruction (incendie) ou de dissimulation malveillante par un héritier lésé qui le trouverait en premier après le décès', 'La mairie l\'invalide'],
          correct: 2, rationale: 'C\'est le drame de nombreux testaments cachés. S\'il n\'est pas trouvé, ce sont les règles légales par défaut qui s\'appliqueront, ruinant les volontés du défunt.' },
        { q: 'Qu\'est-ce qu\'un testament "authentique" ?',
          options: ['Un testament vérifié par la gendarmerie', 'Le vrai testament (le premier), par opposition aux copies', 'Un testament rédigé sur du papier timbré', 'Un testament DICTÉ par le testateur à un notaire, en présence de deux témoins (ou d\'un deuxième notaire), qui le lit à voix haute avant signature'],
          correct: 3, rationale: 'C\'est le testament "blindé". Le notaire s\'assure que la personne a toute sa tête, n\'est pas sous la menace, et que le vocabulaire juridique utilisé est parfait.' },
        { q: 'Quel est l\'inconvénient principal du testament authentique ?',
          options: ['Il est nul en cas de déménagement', 'Il coûte de l\'argent (frais de notaire) et son formalisme est lourd (présence de témoins, impossibilité de garder le contenu totalement secret lors de la rédaction)', 'On ne peut pas le modifier', 'Il ne s\'applique qu\'aux riches'],
          correct: 1, rationale: 'Payer une centaine d\'euros et devoir expliquer ses choix devant des témoins rebute certaines personnes préférant la confidentialité du testament olographe.' },
        { q: 'Comment éviter de perdre un testament "olographe" (manuscrit) tout en gardant sa simplicité ?',
          options: ['L\'envoyer à sa banque', 'L\'enterrer dans le jardin', 'Le rédiger chez soi, puis le confier à un notaire qui le gardera dans son coffre-fort et l\'inscrira au FCDDV (Fichier Central des Dispositions de Dernières Volontés)', 'Le poster sur Facebook'],
          correct: 2, rationale: 'Moyennant un coût dérisoire (~30€), le notaire enregistre l\'existence de votre testament. Au décès, N\'IMPORTE QUEL notaire interrogeant le fichier national saura où il est rangé.' },
        { q: 'Si une personne rédige plusieurs testaments olographes au fil des années, lequel sera appliqué à son décès ?',
          options: ['Tous s\'appliquent en même temps', 'Seul le premier (le plus ancien) est valable', 'Le plus long', 'C\'est le plus RÉCENT (le dernier en date) qui prévaut. Il annule toutes les dispositions contraires des testaments précédents'],
          correct: 3, rationale: 'Un testament est une volonté "jusqu\'à la mort". On peut changer d\'avis 100 fois. C\'est pour cela que la DATE (jour/mois/année) est obligatoire sur le document.' },
        { q: 'En droit français, a-t-on le droit de faire un testament pour léguer tout son argent à un ami, en déshéritant totalement ses enfants ?',
          options: ['Oui, le testament a une valeur supérieure à la loi', 'Non. Les enfants sont des héritiers "réservataires". Le testament ne peut porter QUE sur la "Quotité Disponible" (la part libre du patrimoine). Le testament sera réduit pour restituer leur réserve aux enfants', 'Uniquement s\'ils sont majeurs', 'Oui, si c\'est un testament authentique'],
          correct: 1, rationale: 'Contrairement au droit anglo-saxon, le droit français interdit de déshériter ses enfants.' },
        { q: '(Challenge) Un homme séparé de fait (mais non divorcé) veut priver sa femme de son fameux "Droit viager au logement" (le droit d\'occuper la maison jusqu\'à sa mort). Quel type de testament est OBLIGATOIREMENT exigé par la loi pour cet acte d\'une gravité extrême ?',
          options: ['Un testament olographe très précis', 'Le testament authentique (devant notaire). Un simple testament olographe n\'a aucune valeur pour priver le conjoint de ce droit d\'ordre public', 'Un testament mystique', 'Le juge doit signer'],
          correct: 1, rationale: 'C\'est la protection ultime du conjoint. Il faut la lourde solennité du notaire et des témoins pour qu\'un époux puisse mettre sa femme "à la rue" post-mortem.' },
        { q: '(Challenge) Il existe un 3ème type de testament, le "Testament Mystique". De quoi s\'agit-il ?',
          options: ['Un testament religieux', 'Un document verbal', 'Un acte de magie', 'Le testateur remet un document CLOS, CACHETÉ et SCELLÉ à un notaire en présence de 2 témoins, en affirmant que c\'est son testament. Personne (pas même le notaire) ne connaît son contenu avant le décès'],
          correct: 3, rationale: 'Ce format, rarissime, combine la sécurité de conservation du notaire avec le secret le plus absolu du testament olographe.' },
      ],
